<?php
namespace App\Services\Payments;use App\Models\Payments\EventAdditionalFee;
class AdditionalFeeCalculator{public function calculate(int $eventId,string $channel,int $ticket,int $quantity,array $selected=[]):array{$lines=[];$customer=0;$organizer=0;$fees=EventAdditionalFee::where('event_id',$eventId)->where('is_active',1)->get();foreach($fees as $fee){$channels=(array)($fee->metadata['sales_channels']??[]);if($channels&&!in_array($channel,$channels,true))continue;if(!$fee->is_mandatory&&!in_array($fee->code,$selected,true))continue;$qty=$fee->application==='per_ticket'?$quantity:1;$amount=$fee->calculation_type==='percentage'?(int)round($ticket*(float)$fee->percentage/100):(int)$fee->fixed_amount*$qty;if($amount<=0)continue;$lines[]=['additional_fee_id'=>$fee->id,'code'=>$fee->code,'name'=>$fee->name,'category'=>'additional','bearer'=>$fee->fee_bearer,'quantity'=>$qty,'amount'=>$amount,'calculation_snapshot'=>$fee->toArray()];if($fee->fee_bearer==='customer')$customer+=$amount;else $organizer+=$amount;}return ['lines'=>$lines,'total'=>$customer+$organizer,'customer_total'=>$customer,'organizer_total'=>$organizer];}}
